    """Recolor the uniquely 3x2 rectangular component to the scaffold color."""
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 5) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            comps.append((color, cells))
    out = [row[:] for row in grid]
    candidates = []
    for color, cells in comps:
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        height, width = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        if len(cells) == 6 and height == 3 and width == 2:
            candidates.append((color, cells))
    if len(candidates) == 1:
        _, cells = candidates[0]
        # The demos indicate the odd, non-scaffold motif is recolored to scaffold color;
        # determine this as the color of the long rectilinear frame/line.
        colors = {}
        for row in grid:
            for v in row:
                colors[v] = colors.get(v, 0) + 1
        # Exclude background; among color components the dominant scaffold corresponds
        # to the common long line/frame color, which is the most frequent non-background.
        target = max((v for v in colors if v not in (0, 5)), key=lambda v: colors[v])
        for r,c in cells:
            out[r][c] = target
    return out

